#!/bin/bash
# Wait for the sprite queue, then generate a gameplay-style map (not a poster).
P="$(cd "$(dirname "$0")/.." && pwd)"
until grep -q ALLDONE $P/assets/raw/gen.log; do sleep 20; done
cd $P/assets/raw
[ -s world-game.png ] || codex exec --skip-git-repo-check -s workspace-write -C $P/assets/raw "Use your image generation tool to create ONE NEW image (never reuse an existing file) and save it as $P/assets/raw/world-game.png (1536x1024 landscape). It must look like an actual playable GAME MAP from a 2D RPG (like the overworld of an SNES/GBA-era or modern HD-2D RPG), NOT a poster or illustration: strict top-down 3/4 camera with one consistent perspective, terrain fills the whole frame edge to edge (no sky, no horizon, no sunset, no clouds framing the edges, no floating islands), even daylight, readable tile-like ground (grass, dirt, water, stone), wide light-stone ROADS clearly connecting ten compact areas: a royal castle with a plaza and fountain in the center; a blacksmith forge town with anvils and furnaces (west); an elven forest clearing with treehouses (north-west); a wizard tower with a small courtyard (north); a star observatory dome on a hill (north-east of center); a white holy cathedral with stairs (east); a dark volcanic fortress gate with lava pools and a big empty chained platform (far north-east); a steampunk harbor with docks, cranes and a moored airship (south-east, by the sea); a cozy inn village with a campfire square (south-west); a gold vault with treasure piles and a courtyard (south). Each area has an open walkable square in front for characters to stand and fight. No characters, no monsters, no text, no labels, no UI. Clean pixel-art rendering with crisp edges." < /dev/null > world-game.png.log 2>&1
echo "world-game rc=$? $(md5sum world-game.png 2>/dev/null | cut -c1-8)" >> $P/assets/raw/gen.log
echo MAP2DONE >> $P/assets/raw/gen.log
